    {
        public void Execute(ExecutionResult result)
        {
            var target = Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None).Single(f => f.name == "Photo inspired HiTech");
            var original = AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>("Assets/CampusSim/Generated/HiTechFacade/Massing.asset");
