                throw new System.Exception("Unexpected facade extents");
            for (int i = 0; i < vertices.Length; i++)
            {
                var v = world[i];
                v.x = roadClearX + (v.x - min) * (max - roadClearX) / (max - min);
                vertices[i] = target.transform.InverseTransformPoint(v);
            }

            source.vertices = vertices;
            source.RecalculateNormals();
            source.RecalculateBounds();
            const string path = "Assets/CampusSim/Generated/HitechRoadRepair/Massing_road_clearance.asset";
            var mesh = AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>(path);
            if (!mesh)
            {
                mesh = source;
                mesh.name = "Massing_road_clearance";
                AssetDatabase.CreateAsset(mesh, path);
            }
            else
            {
                EditorUtility.CopySerialized(source, mesh);
                mesh.name = "Massing_road_clearance";
                Object.DestroyImmediate(source);
                EditorUtility.SetDirty(mesh);
            }

            Undo.RecordObject(target, "Fit road-facing facade");
            target.sharedMesh = mesh;
            var collider = target.GetComponent<MeshCollider>();
            Undo.RecordObject(collider, "Fit matching facade collider");
            collider.sharedMesh = null;
            collider.sharedMesh = mesh;
            Physics.SyncTransforms();
            AssetDatabase.SaveAssets();
            if (!EditorApplication.isPlaying)
            {
                EditorSceneManager.MarkSceneDirty(target.gameObject.scene);
                EditorSceneManager.SaveScene(target.gameObject.scene);
            }

            result.Log("FACADE_CLEARANCE min_x=" + min + " -> " + roadClearX + " max_x_preserved=" + max + " source_unchanged=true playing=" + EditorApplication.isPlaying);
        }
    }
